function foodCategoryByName(n){
  const s=String(n||'').toLowerCase().trim();
  if(FOOD_CATEGORY_OVERRIDES[n])return FOOD_CATEGORY_OVERRIDES[n];
  if(/максым|чалап|аралаш|жарма|бозо|(?:^|[^а-яё])тан(?:$|[^а-яё])|квас|кока|pepsi|sprite|fanta|сок|вода|напит/.test(s))return 'Напитки';
  if(/суп|борщ|щи|шорпо|солян|окрош|уха/.test(s))return 'Супы';
  if(/салат|винегрет|закуск/.test(s))return 'Салаты и закуски';
  if(/шоколад|печенье|зефир|пастила|мёд|сахар|конфет|торт|морожен|десерт/.test(s))return 'Сладости и десерты';
  if(/сыр|творог|молоко|кефир|йогурт|сметана|ряженка|сливк|фета|пармезан|маскарпоне|рикотта|(?:^|[^а-яё])бри(?:$|[^а-яё])|камамбер|рокфор|дорблю|сулугуни|брынза|гауда|эдам|чеддер|эмменталь|грюйер|маасдам|тильзит|голланд|российский|костром|пошех|провол|мюнстер|бургомистр|швейцар/.test(s))return 'Молочные продукты';
  if(/яйц|омлет|яичниц|скрэмбл/.test(s))return 'Яйца';
  if(/рыб|лосос|тунец|треск|минтай|судак|форел|скумбр|сельд|кревет|кальмар|мидии|икра/.test(s))return 'Рыба и морепродукты';
  if(/кур(?!уз)|индей|говядин|свин|баран|конин|телят|кролик|печень|сосиск|ветчин/.test(s))return 'Мясо и птица';
  if(/орех|миндаль|фисташ|кешью|пекан|макадам|фундук|семеч|семена|кунжут|арахис/.test(s))return 'Орехи и семена';
  if(/фасол|горох|маш|соя|нут|чечев|хумус/.test(s))return 'Бобовые';
  if(/хлеб|лаваш|хлебец|сухар|крекер|блин|олад/.test(s))return 'Хлеб и выпечка';
  if(/греч|рис|перлов|пшено|булгур|киноа|кукуруз|манн|овся|макарон|спагетти|вермиш|каша|картоф|батат/.test(s))return 'Крупы и гарниры';
  if(/яблок|банан|апельс|мандар|груш|киви|персик|абрикос|слив|виноград|арбуз|дын|лимон|лайм|помело|нектарин|хурм|гранат|манго|ананас|папай|инжир|финик/.test(s))return 'Фрукты';
  if(/клубник|малин|черник|ежевик|смородин|крыжов|клюкв|череш|вишн/.test(s))return 'Ягоды';
  if(/масло|майонез|томатная паста|соус|приправа/.test(s))return 'Масла, соусы и приправы';
  if(/огур|помид|морков|капуст|брокк|цветн|перец|кабач|баклаж|св[её]кл|тыкв|шпинат|фасоль зел|авокадо|гриб|лук|чеснок|оливк|маслин|руккол|петруш|укроп|редис|брюссель|кольраби|спарж|сельдер/.test(s))return 'Овощи и зелень';
  return 'Готовые блюда';
}
