function syncRecordMap(state){
  const m={};
  const put=(type,id,payload)=>{if(id==null)return;m[type+'|'+id]=syncClone(payload)};
  put('profile','singleton',state.profile||{}); put('settings','singleton',state.settings||{}); put('preferences','singleton',state.preferences||{}); put('ratios','singleton',state.ratios||{}); put('favorites','singleton',state.favorites||{});
  const medical=syncClone(state.medical||{}); if(medical){delete medical.calculationLog;delete medical.actualInsulinLog;} put('medical.profile','singleton',medical);
  (state.diary||[]).forEach(x=>x?.id&&put('diary',x.id,x)); (state.activity||[]).forEach(x=>x?.id&&put('activity',x.id,x)); (state.recipes||[]).forEach(x=>x?.id&&put('recipes',x.id,x));
  (state.medical?.calculationLog||[]).forEach(x=>x?.id&&put('medical.calculationLog',x.id,x)); (state.medical?.actualInsulinLog||[]).forEach(x=>x?.id&&put('medical.actualInsulin',x.id,x));
  Object.entries(state.menus||{}).forEach(([day,items])=>put('menu',day,{day,items:Array.isArray(items)?items:[]}));
  return m;
}
function syncQueueLocalChanges(previous,current){
  if(!window.DMFamily)return;
  const prev=syncRecordMap(previous||{}), cur=syncRecordMap(current||{}), events=[];
  const keys=new Set([...Object.keys(prev),...Object.keys(cur)]);
  for(const k of keys){const a=prev[k],b=cur[k];if(JSON.stringify(a)===JSON.stringify(b))continue;const [recordType,recordId]=k.split('|');
    const base=Number(current.sync?.remoteVersions?.[k]||0); const event={clientEventId:DMFamily.recordChange(current,recordType,recordId,b==null?'delete':'upsert',current.identity?.currentUser?.id).id,recordType,recordId,operation:b==null?'delete':'upsert',payload:b,baseVersion:base||undefined,immutable:['medical.calculationLog','medical.actualInsulin'].includes(recordType),installationId:current.identity?.installation?.id||null,clientUpdatedAt:new Date().toISOString()};
    // Replace the lightweight local change with the transport payload.
    const q=current.sync.queue||[]; const idx=q.findIndex(x=>x.id===event.clientEventId); if(idx>=0)Object.assign(q[idx],event); else q.push(event); events.push(event);
  }
  current.sync.queue=current.sync.queue||[]; if(current.sync.queue.length>1000)current.sync.queue=current.sync.queue.slice(-1000); return events;
}
function applyRemoteChange(ch){
  const rt=ch.recordType,rid=ch.recordId,p=ch.payload; db.sync=db.sync||{};db.sync.remoteVersions=db.sync.remoteVersions||{};db.sync.remoteVersions[rt+'|'+rid]=Number(ch.version||1);
  if(ch.deleted)return;
  if(rt==='profile')db.profile=p||{}; else if(rt==='settings')db.settings=p||{}; else if(rt==='preferences')db.preferences=p||{}; else if(rt==='ratios')db.ratios=p||{}; else if(rt==='favorites')db.favorites=p||{}; else if(rt==='medical.profile'){db.medical={...(db.medical||{}),...(p||{})};}
  else if(rt==='diary'||rt==='activity'||rt==='recipes'){db[rt]=Array.isArray(db[rt])?db[rt]:[];const i=db[rt].findIndex(x=>String(x.id)===String(rid));if(i>=0)db[rt][i]=p;else db[rt].push(p);}
  else if(rt==='medical.calculationLog'||rt==='medical.actualInsulin'){db.medical=db.medical||{};const prop=rt==='medical.calculationLog'?'calculationLog':'actualInsulinLog';db.medical[prop]=Array.isArray(db.medical[prop])?db.medical[prop]:[];const i=db.medical[prop].findIndex(x=>String(x.id)===String(rid));if(i>=0)db.medical[prop][i]=p;else db.medical[prop].push(p);}
  else if(rt==='menu'){db.menus=db.menus||{};db.menus[rid]=p?.items||[];}
}
async function cloudRecordSync(silent){
  if(!db.cloud?.authenticated||!window.DMCloud)return;
  try{
    const api=DMCloud.create(db.cloud.baseUrl); const q=(db.sync?.queue||[]).slice(0,100); db.sync.conflictKeys=db.sync.conflictKeys||{};
    if(q.length){const r=await api.pushChanges(db.identity.activePatientId,q); if(r.accepted?.length){const ids=new Set(r.accepted.map(x=>x.clientEventId).filter(Boolean));db.sync.queue=(db.sync.queue||[]).filter(x=>!ids.has(x.clientEventId));(r.accepted||[]).forEach(x=>{if(x.record){const k=x.record.recordType+'|'+x.record.recordId;db.sync.remoteVersions=db.sync.remoteVersions||{};db.sync.remoteVersions[k]=Number(x.record.version||1);}});}
      if(r.conflicts?.length){db.cloud.conflict=true;db.sync.status='conflict';(r.conflicts||[]).forEach(c=>{if(c.recordType&&c.recordId)db.sync.conflictKeys[c.recordType+'|'+c.recordId]=true;});}
    }
    let cursor=Number(db.sync?.serverCursor||0); const pull=await api.pullChanges(db.identity.activePatientId,cursor,500); (pull.changes||[]).forEach(ch=>{const k=ch.recordType+'|'+ch.recordId;if(!db.sync.conflictKeys?.[k])applyRemoteChange(ch);}); db.sync.serverCursor=Number(pull.cursor||cursor); db.sync.status=pull.conflicts?.length?'conflict':'cloud-sync'; db.sync.lastSyncAt=new Date().toISOString(); storage.save(db); syncShadowSave(syncRecordMap(db));
  }catch(e){db.sync.status='offline';if(!silent)alert(e.message||'Не удалось синхронизировать записи.');storage.save(db)}
}
function save(){
  window.db=db; const previous=syncShadowLoad(); if(previous && db.cloud?.authenticated)syncQueueLocalChanges(previous,db); storage.save(db); syncShadowSave(syncRecordMap(db));
  if(db.cloud?.authenticated&&window.DMCloud){clearTimeout(cloudPushTimer);cloudPushTimer=setTimeout(()=>cloudRecordSync(true),900)}
}function familyEsc(v){return reportEscape(String(v??''))}
function familyRoleLabel(r){return DMFamily.ROLES[r]||r||'—'}
