  const glucose=(db.diary||[]).filter(x=>inRange(x.date)&&Number.isFinite(+x.g)).sort((a,b)=>dateTimeOf(a).localeCompare(dateTimeOf(b)));const actual=(db.medical?.actualInsulinLog||[]).filter(x=>inRange(x.date));const acts=(db.activity||[]).filter(x=>inRange(x.date));const activeDays=new Set([...menus.map(x=>x.date),...glucose.map(x=>x.date),...acts.map(x=>x.date)]).size;
  document.getElementById('mpDays').textContent=activeDays;document.getElementById('mpMeals').textContent=menus.length;document.getElementById('mpGlucose').textContent=glucose.length;document.getElementById('mpInsulin').textContent=actual.reduce((a,x)=>a+(+x.units||0),0).toFixed(1)+' ЕД';
  let freq={};menus.forEach(m=>m.items.forEach(i=>freq[i.name]=(freq[i.name]||0)+1));let top=Object.entries(freq).sort((a,b)=>b[1]-a[1]).slice(0,7);document.getElementById('mpFoodPatterns').innerHTML=top.length?top.map((x,i)=>`<div class="mini" style="margin:7px 0"><div class="row" style="justify-content:space-between"><b>${i+1}. ${reportEscape(x[0])}</b><span class="pill">${x[1]} запис.</span></div></div>`).join(''):'<p class="muted">Недостаточно пищевых записей.</p>';
  let linked=[];menus.forEach(m=>{let before=glucose.filter(g=>g.date===m.date&&g.time).sort((a,b)=>Math.abs(minutesOf(a.time)-mealAnchor(m.meal))-Math.abs(minutesOf(b.time)-mealAnchor(m.meal)))[0];if(before)linked.push({m,before})});let byMeal={};linked.forEach(x=>{let k=x.m.meal;(byMeal[k]??=[]).push(+x.before.g)});let mealRows=Object.entries(byMeal).map(([k,v])=>({k,n:v.length,avg:v.reduce((a,b)=>a+b,0)/v.length})).sort((a,b)=>b.n-a.n);document.getElementById('mpMealGlucose').innerHTML=mealRows.length?mealRows.map(x=>`<div class="mini" style="margin:7px 0"><b>${reportEscape(x.k)}</b><br><span class="muted">${x.n} связ. измер. · среднее записанное значение ${x.avg.toFixed(1)} ммоль/л</span></div>`).join(''):'<p class="muted">Пока недостаточно совпадающих по времени записей.</p>';
  let mins=acts.reduce((a,x)=>a+(+x.minutes||0),0),actDays=new Set(acts.map(x=>x.date)).size;document.getElementById('mpActivity').innerHTML=`<div class="kpi"><div class="mini"><span class="muted">Минут</span><b>${mins}</b></div><div class="mini"><span class="muted">Дней</span><b>${actDays}</b></div><div class="mini"><span class="muted">Записей</span><b>${acts.length}</b></div></div>`+(acts.length?`<p class="muted">Чаще всего: ${reportEscape(mostCommon(acts.map(x=>x.type||'нагрузка')))}</p>`:'<p class="muted">Активность пока не записывалась.</p>');
  let basal=actual.filter(x=>x.type==='Базальный').reduce((a,x)=>a+(+x.units||0),0),bolus=actual.filter(x=>x.type==='Болюс'||x.type==='Коррекция').reduce((a,x)=>a+(+x.units||0),0);document.getElementById('mpInsulinDetail').innerHTML=`<div class="kpi"><div class="mini"><span class="muted">Всего</span><b>${actual.reduce((a,x)=>a+(+x.units||0),0).toFixed(1)} ЕД</b></div><div class="mini"><span class="muted">Базальный</span><b>${basal.toFixed(1)} ЕД</b></div><div class="mini"><span class="muted">Болюс/корр.</span><b>${bolus.toFixed(1)} ЕД</b></div></div><p class="muted">Показываются только фактически зарегистрированные введения.</p>`;
  let obs=[];if(top[0]&&top[0][1]>=3)obs.push(`Чаще всего в записях встречается «${top[0][0]}» — ${top[0][1]} раз.`);if(menus.length>=5){let avgCarbs=menus.reduce((a,x)=>a+x.carbs,0)/menus.length;obs.push(`Среднее записанное количество углеводов на приём пищи: ${avgCarbs.toFixed(1)} г.`)}if(glucose.length>=5){let avgG=glucose.reduce((a,x)=>a+(+x.g),0)/glucose.length;obs.push(`Среднее значение глюкозы среди записанных измерений: ${avgG.toFixed(1)} ммоль/л.`)}if(acts.length&&mins)obs.push(`За период записано ${mins} минут физической активности.`);if(!obs.length)obs.push('Нужно больше записей, чтобы показать персональные наблюдения.');document.getElementById('mpObservations').innerHTML=obs.map(x=>`<div class="mini" style="margin:7px 0">${reportEscape(x)}</div>`).join('');
  renderScenarioRecommendations();
