function mostCommon(a){let m={};a.forEach(x=>m[x]=(m[x]||0)+1);return Object.entries(m).sort((a,b)=>b[1]-a[1])[0]?.[0]||'—'}
function minutesOf(t){let [h,m]=(t||'00:00').split(':').map(Number);return h*60+m}
function mealAnchor(meal){return ({'Завтрак':8*60,'Перекус 1':10*60+30,'Обед':13*60,'Перекус 2':16*60,'Ужин':19*60,'Перекус 3':21*60})[meal]||12*60}
