function medicationClassOptions(){return MEDICATION_CLASSES.map(x=>`<option>${x}</option>`).join('')}
function composeFullName(p){return [p.surname,p.firstName].filter(Boolean).join(' ').trim()||p.name||''}
const INSULIN_OPTIONS={basal:[['','Не указано'],['detemir','Levemir — инсулин детемир'],['glargine-u100','Lantus / Semglee / Basaglar — инсулин гларгин U-100'],['glargine-u300','Toujeo — инсулин гларгин U-300'],['degludec','Tresiba — инсулин деглудек'],['nph','NPH / изофан-инсулин'],['other','Другой / указать в примечании']],bolus:[['','Не указано'],['glulisine','Apidra — инсулин глулизин'],['aspart','NovoRapid — инсулин аспарт'],['lispro','Humalog — инсулин лизпро'],['faster-aspart','Fiasp — инсулин аспарт ускоренного действия'],['lispro-ultra','Lyumjev — инсулин лизпро ускоренного действия'],['regular','Regular human insulin — короткого действия'],['other','Другой / указать в примечании']]};function insulinOptions(kind){return INSULIN_OPTIONS[kind].map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}function saveMedical(){db.medical={...db.medical,a1c:mA1c.value,cp:mCP.value,gad:mGAD.value,ia2:mIA2.value,zn:mZn.value,gen:mGen.value,regimen:mRegimen.value,basal:mBasal.value,bolus:mBolus.value,ins:mIns.value,date:mDate.value,note:mNote.value,cgm:{active:cgmActive.value==='yes',manufacturer:cgmManufacturer.value,product:cgmProduct.value,model:cgmModel.value,generation:cgmGeneration.value,source:cgmSource.value,connection:cgmConnection.value},medications:[{genericName:medName.value,brandName:medName.value,class:medClass.value,form:medForm.value,dose:medDose.value,doseUnit:medDoseUnit.value,frequency:medFrequency.value,timing:medTiming.value,route:medRoute.value,startDate:medStart.value,endDate:medEnd.value,active:medActive.value==='true',notes:medNote.value}].filter(x=>x.genericName||x.brandName)};save();alert('Медицинские данные сохранены')}
function renderMedical(){let m=db.medical||{},c=m.cgm||{},med=(m.medications||[])[0]||{};mA1c.value=m.a1c||'';mCP.value=m.cp||'';mGAD.value=m.gad||'';mIA2.value=m.ia2||'';mZn.value=m.zn||'';mGen.value=m.gen||'';mRegimen.value=m.regimen||'Не указано';mBasal.innerHTML=insulinOptions('basal');mBolus.innerHTML=insulinOptions('bolus');mBasal.value=m.basal||'';mBolus.value=m.bolus||'';mIns.value=m.ins||'';mDate.value=m.date||'';mNote.value=m.note||'';cgmManufacturer.innerHTML=cgmManufacturerOptions();cgmManufacturer.value=c.manufacturer||'Не указано';cgmActive.value=c.active?'yes':'no';cgmProduct.value=c.product||'';cgmModel.value=c.model||'';cgmGeneration.value=c.generation||'';cgmSource.value=c.source||'Не указано';cgmConnection.value=c.connection||'Не подключено';medClass.innerHTML=medicationClassOptions();medName.value=med.genericName||med.brandName||'';medClass.value=med.class||'Не указано';medForm.value=med.form||'';medDose.value=med.dose||'';medDoseUnit.value=med.doseUnit||'';medFrequency.value=med.frequency||'';medTiming.value=med.timing||'';medRoute.value=med.route||'Не указано';medStart.value=med.startDate||'';medEnd.value=med.endDate||'';medActive.value=med.active===false?'false':'true';medNote.value=med.notes||''}
function initDoctorReport(){let e=document.getElementById('reportEnd');if(e&&!e.value)e.value=today();}
function reportRange(){let end=document.getElementById('reportEnd')?.value||today(),days=+(document.getElementById('reportPeriod')?.value||30),d=new Date(end+'T12:00:00');d.setDate(d.getDate()-days+1);return {start:d.toISOString().slice(0,10),end};}
function reportEscape(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function reportChart(values){if(!values.length)return '<div class="mini muted">Нет достаточных данных для графика.</div>';let w=760,h=220,p=36,nums=values.map(x=>x.v),mn=Math.min(...nums),mx=Math.max(...nums);if(mn===mx){mn-=1;mx+=1}let pts=values.map((x,i)=>{let X=p+(i*(w-2*p)/Math.max(1,values.length-1)),Y=h-p-(x.v-mn)*(h-2*p)/(mx-mn);return [X,Y,x]});let poly=pts.map(x=>x[0].toFixed(1)+','+x[1].toFixed(1)).join(' ');return `<div class="mini"><b>Средняя глюкоза по дням</b><svg viewBox="0 0 ${w} ${h}" style="width:100%;height:auto;display:block"><line x1="${p}" y1="${p}" x2="${p}" y2="${h-p}" stroke="currentColor" opacity=".2"/><line x1="${p}" y1="${h-p}" x2="${w-p}" y2="${h-p}" stroke="currentColor" opacity=".2"/><polyline points="${poly}" fill="none" stroke="currentColor" stroke-width="2"/>${pts.map(a=>`<circle cx="${a[0].toFixed(1)}" cy="${a[1].toFixed(1)}" r="3"><title>${reportEscape(a[2].date)}: ${a[2].v.toFixed(1)} ммоль/л</title></circle>`).join('')}<text x="${p}" y="${h-8}" font-size="10">${reportEscape(values[0].date)}</text><text x="${w-p}" y="${h-8}" font-size="10" text-anchor="end">${reportEscape(values[values.length-1].date)}</text><text x="${p-5}" y="${p+4}" font-size="10" text-anchor="end">${mx.toFixed(1)}</text><text x="${p-5}" y="${h-p+4}" font-size="10" text-anchor="end">${mn.toFixed(1)}</text></svg></div>`}
function actualInsulinDateTime(x){return String(x.date||'')+(x.time?'T'+x.time:'')}
function renderActualInsulin(){let m=db.medical||{};let list=Array.isArray(m.actualInsulinLog)?m.actualInsulinLog:[];let d=document.getElementById('actualInsDate'),t=document.getElementById('actualInsTime');if(d&&!d.value)d.value=today();if(t&&!t.value)t.value=new Date().toTimeString().slice(0,5);let sel=document.getElementById('actualInsCalc');if(sel){let logs=(m.calculationLog||[]).slice(-20).reverse();sel.innerHTML='<option value="">Не связывать</option>'+logs.map(x=>`<option value="${reportEscape(x.id||'')}">${reportEscape(String(x.timestamp||'').replace('T',' ').slice(0,16))} — ${reportEscape(x.result&&x.result.dose!=null?x.result.dose+' ЕД':'расчёт')}</option>`).join('')}let el=document.getElementById('actualInsulinList');if(!el)return;let rows=list.slice().sort((a,b)=>actualInsulinDateTime(b).localeCompare(actualInsulinDateTime(a))).slice(0,20);el.innerHTML=rows.length?'<div class="tablewrap"><table class="tbl"><thead><tr><th>Дата</th><th>Время</th><th>Тип</th><th>ЕД</th><th>Контекст</th><th>Расчёт</th><th></th></tr></thead><tbody>'+rows.map(x=>`<tr><td>${reportEscape(x.date||'—')}</td><td>${reportEscape(x.time||'—')}</td><td>${reportEscape(x.type||'—')}</td><td>${Number(x.units||0).toFixed(1)}</td><td>${reportEscape(x.reason||'—')}</td><td>${x.calculationId?'Связан':'—'}</td><td><button class="btn secondary" onclick="deleteActualInsulin('${reportEscape(x.id)}')">Удалить</button></td></tr>`).join('')+'</tbody></table></div>':'<p class="muted">Записей пока нет.</p>'}
function saveActualInsulin(){let units=Number(document.getElementById('actualInsUnits')?.value);if(!Number.isFinite(units)||units<=0){alert('Укажите фактически введённую дозу в ЕД.');return}db.medical=db.medical||{};db.medical.actualInsulinLog=Array.isArray(db.medical.actualInsulinLog)?db.medical.actualInsulinLog:[];let rec={id:'ai-'+Date.now()+'-'+Math.random().toString(36).slice(2,8),date:document.getElementById('actualInsDate').value||today(),time:document.getElementById('actualInsTime').value||'',type:document.getElementById('actualInsType').value,units,reason:document.getElementById('actualInsReason').value,calculationId:document.getElementById('actualInsCalc').value||'',note:document.getElementById('actualInsNote').value||'',recordedAt:new Date().toISOString(),appVersion:APP_VERSION};db.medical.actualInsulinLog.push(rec);if(db.medical.actualInsulinLog.length>1000)db.medical.actualInsulinLog.splice(0,db.medical.actualInsulinLog.length-1000);save();document.getElementById('actualInsUnits').value='';document.getElementById('actualInsNote').value='';renderActualInsulin();alert('Фактическое введение записано.')}
function deleteActualInsulin(id){db.medical=db.medical||{};db.medical.actualInsulinLog=(db.medical.actualInsulinLog||[]).filter(x=>x.id!==id);save();renderActualInsulin()}

function generateDoctorReport(){let el=document.getElementById('doctorReport');if(!el)return;let rg=reportRange(),p=db.profile||{},m=db.medical||{},redact=document.getElementById('reportRedact')?.checked,questions=(document.getElementById('reportQuestions')?.value||'').trim();let glucose=(db.diary||[]).filter(x=>x.date>=rg.start&&x.date<=rg.end&&Number.isFinite(+x.g)),gv=glucose.map(x=>+x.g),avg=gv.length?gv.reduce((a,b)=>a+b,0)/gv.length:0,min=gv.length?Math.min(...gv):null,max=gv.length?Math.max(...gv):null,days=new Set(glucose.map(x=>x.date)).size;let daily={};glucose.forEach(x=>(daily[x.date]??=[]).push(+x.g));let dailyAvg=Object.entries(daily).map(([date,v])=>({date,v:v.reduce((a,b)=>a+b,0)/v.length}));let meals=[];Object.entries(db.menus||{}).forEach(([date,menu])=>{if(date<rg.start||date>rg.end)return;Object.values(menu||{}).flat().forEach(it=>{let f=(db.foods||[]).find(x=>x.id===it.foodId);if(f)meals.push({date,name:f.name,kcal:(+f.kcal||0)*(+it.g||0)/100,c:(+f.c||0)*(+it.g||0)/100,p:(+f.p||0)*(+it.g||0)/100,fat:(+f.f||0)*(+it.g||0)/100})})});let sums=meals.reduce((a,x)=>{a.kcal+=x.kcal;a.c+=x.c;a.p+=x.p;a.fat+=x.fat;return a},{kcal:0,c:0,p:0,fat:0});let freq={};meals.forEach(x=>freq[x.name]=(freq[x.name]||0)+1);let topFoods=Object.entries(freq).sort((a,b)=>b[1]-a[1]).slice(0,10);let dayFood={};meals.forEach(x=>{dayFood[x.date]??={count:0,kcal:0,c:0};dayFood[x.date].count++;dayFood[x.date].kcal+=x.kcal;dayFood[x.date].c+=x.c;});let acts=(db.activity||[]).filter(x=>x.date>=rg.start&&x.date<=rg.end),activityMinutes=acts.reduce((a,x)=>a+(+x.minutes||0),0);let calc=(m.calculationLog||[]).filter(x=>String(x.timestamp||'').slice(0,10)>=rg.start&&String(x.timestamp||'').slice(0,10)<=rg.end),valid=calc.filter(x=>x.result&&x.result.valid),insulinTotal=valid.reduce((a,x)=>a+(+x.result.dose||0),0),actual=(m.actualInsulinLog||[]).filter(x=>String(x.date||x.timestamp||'').slice(0,10)>=rg.start&&String(x.date||x.timestamp||'').slice(0,10)<=rg.end),meds=(m.medications||[]).filter(x=>x.genericName||x.brandName),name=composeFullName(p)||p.name||'Не указано';let qhtml=questions?'<ol>'+questions.split(/\n+/).filter(Boolean).map(q=>'<li>'+reportEscape(q)+'</li>').join('')+'</ol>':'<p class="muted">Вопросы не добавлены.</p>';let rows=Object.entries(dayFood).sort();let html=`<div id="doctorReportPrintable"><div class="row" style="justify-content:space-between"><div><h2>Отчёт для медицинского специалиста</h2><p style="font-size:1.2em"><b>Пациент:</b> ${reportEscape(name)}</p><p><b>Период:</b> ${rg.start} — ${rg.end}</p></div><div class="muted">Сформирован: ${new Date().toLocaleString('ru-RU')}</div></div><hr><h3>1. Профиль пациента</h3><p><b>Тип диабета:</b> ${reportEscape(p.type||'Не указан')} · <b>Дата рождения:</b> ${redact?'Скрыта':reportEscape(p.dob||'Не указана')} · <b>Пол:</b> ${reportEscape(p.sex||'Не указан')}</p><h3>2. Инсулинотерапия</h3><p><b>Режим:</b> ${reportEscape(m.regimen||'Не указан')} · <b>Базальный:</b> ${reportEscape(m.basal||'Не указан')} · <b>Болюсный:</b> ${reportEscape(m.bolus||'Не указан')}</p><p><b>Примечание:</b> ${reportEscape(m.ins||'—')}</p><h3>3. Глюкоза</h3><div class="kpi"><div class="mini"><span class="muted">Измерений</span><b>${gv.length}</b></div><div class="mini"><span class="muted">Дней</span><b>${days}</b></div><div class="mini"><span class="muted">Среднее</span><b>${avg?avg.toFixed(1):'—'} ммоль/л</b></div><div class="mini"><span class="muted">Мин.</span><b>${min==null?'—':min.toFixed(1)}</b></div><div class="mini"><span class="muted">Макс.</span><b>${max==null?'—':max.toFixed(1)}</b></div></div>${reportChart(dailyAvg)}<p class="muted">TIR/TAR/TBR не рассчитываются по точечным измерениям; для них нужен временной ряд CGM с корректными интервалами.</p><h3>4. Питание</h3><p><b>Позиций:</b> ${meals.length} · <b>Энергия:</b> ${sums.kcal.toFixed(0)} ккал · <b>Углеводы:</b> ${sums.c.toFixed(1)} г · <b>Белки:</b> ${sums.p.toFixed(1)} г · <b>Жиры:</b> ${sums.fat.toFixed(1)} г</p><div class="mini"><b>Часто записываемые продукты/блюда</b>${topFoods.length?'<ol>'+topFoods.map(x=>'<li>'+reportEscape(x[0])+' — '+x[1]+' раз</li>').join('')+'</ol>':'<p class="muted">Нет записей.</p>'}</div><div class="mini" style="margin-top:10px"><b>Дневная разбивка</b>${rows.length?'<table style="width:100%;border-collapse:collapse"><tr><th>Дата</th><th>Позиций</th><th>ккал</th><th>Углеводы, г</th></tr>'+rows.map(([d,x])=>`<tr><td>${d}</td><td>${x.count}</td><td>${x.kcal.toFixed(0)}</td><td>${x.c.toFixed(1)}</td></tr>`).join('')+'</table>':'<p class="muted">Нет записей.</p>'}</div><h3>5. Физическая активность</h3><p><b>Всего:</b> ${activityMinutes} мин · <b>Записей:</b> ${acts.length}</p>${acts.length?'<table style="width:100%;border-collapse:collapse"><tr><th>Дата</th><th>Вид</th><th>Мин.</th><th>Интенсивность</th></tr>'+acts.map(x=>`<tr><td>${x.date}</td><td>${reportEscape(x.type||'—')}</td><td>${x.minutes||0}</td><td>${reportEscape(x.intensity||'—')}</td></tr>`).join('')+'</table>':'<p class="muted">Нет записей активности.</p>'}<h3>6. Инсулиновые расчёты</h3><p><b>Расчётов:</b> ${calc.length} · <b>Валидных:</b> ${valid.length} · <b>Сумма рассчитанных доз:</b> ${insulinTotal.toFixed(1)} ЕД</p><p class="muted">Рассчитанная доза не равна подтверждённой фактически введённой дозе.</p><h3>7. Фактически введённый инсулин</h3>${actual.length?`<p><b>Записей:</b> ${actual.length} · <b>Всего:</b> ${actual.reduce((a,x)=>a+(+x.units||0),0).toFixed(1)} ЕД</p><table style="width:100%;border-collapse:collapse"><tr><th>Дата</th><th>Время</th><th>Тип</th><th>ЕД</th><th>Контекст</th></tr>${actual.slice().sort((a,b)=>actualInsulinDateTime(a).localeCompare(actualInsulinDateTime(b))).map(x=>`<tr><td>${reportEscape(x.date||'—')}</td><td>${reportEscape(x.time||'—')}</td><td>${reportEscape(x.type||'—')}</td><td>${Number(x.units||0).toFixed(1)}</td><td>${reportEscape(x.reason||'—')}</td></tr>`).join('')}</table>`:'<p class="muted">Журнал фактически введённого инсулина пока не ведётся. Расчёты не считаются фактом введения.</p>'}<h3>8. CGM</h3><p><b>Используется:</b> ${(m.cgm&&m.cgm.active)?'Да':'Нет'} · <b>Производитель:</b> ${reportEscape(m.cgm?.manufacturer||'—')} · <b>Продукт:</b> ${reportEscape(m.cgm?.product||'—')} · <b>Модель:</b> ${reportEscape(m.cgm?.model||'—')} · <b>Поколение:</b> ${reportEscape(m.cgm?.generation||'—')} · <b>Источник:</b> ${reportEscape(m.cgm?.source||'—')} · <b>Статус:</b> ${reportEscape(m.cgm?.connection||'—')}</p><h3>9. Лекарственная терапия</h3>${meds.length?'<table style="width:100%;border-collapse:collapse"><tr><th>Препарат</th><th>Класс</th><th>Доза</th><th>Частота</th><th>Статус</th></tr>'+meds.map(x=>`<tr><td>${reportEscape(x.genericName||x.brandName||'—')}</td><td>${reportEscape(x.class||'—')}</td><td>${reportEscape(x.dose||'—')} ${reportEscape(x.doseUnit||'')}</td><td>${reportEscape(x.frequency||'—')}</td><td>${x.active?'Сейчас':'Не принимает'}</td></tr>`).join('')+'</table>':'<p class="muted">Препараты не указаны.</p>'}<h3>10. Лабораторные данные</h3><p><b>HbA1c:</b> ${reportEscape(m.a1c||(latestLab('hba1c')?latestLab('hba1c').value+' % ('+latestLab('hba1c').date+')':'—'))} · <b>C-пептид:</b> ${reportEscape(m.cp||(latestLab('cpep')?latestLab('cpep').value+' '+latestLab('cpep').unit+' ('+latestLab('cpep').date+')':'—'))} · <b>GAD:</b> ${reportEscape(m.gad||'—')} · <b>IA-2:</b> ${reportEscape(m.ia2||'—')} · <b>ZnT8:</b> ${reportEscape(m.zn||'—')}</p><p><b>Примечания:</b> ${reportEscape(m.note||'—')}</p>${(db.labs||[]).length?'<p><b>Анализы:</b></p><ul>'+(db.labs||[]).slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,20).map(x=>'<li>'+reportEscape(x.date+' — '+x.name+': '+x.value+' '+(x.unit||''))+'</li>').join('')+'</ul>':''}${[db.profile?.bloodGroup&&('Группа крови: '+db.profile.bloodGroup+' '+(db.profile.rh||'')),db.profile?.diet&&('Тип питания: '+db.profile.diet),db.profile?.diseases&&('Сопутствующие заболевания: '+db.profile.diseases),db.profile?.allergies&&('Аллергии: '+db.profile.allergies)].filter(Boolean).map(x=>'<p>'+reportEscape(x)+'</p>').join('')}<h3>11. Вопросы для врача</h3>${qhtml}<hr><p class="muted">Отчёт автоматически сформирован из записей приложения. Он предназначен для обсуждения с медицинским специалистом и не является диагнозом, назначением или медицинским заключением.</p></div>`;el.innerHTML=html;el.style.display='block'}
function printDoctorReport(){if(document.getElementById('doctorReport')?.style.display==='none'||!document.getElementById('doctorReport')?.innerHTML)generateDoctorReport();setTimeout(()=>window.print(),100)}

function saveSettings(){db.settings.target=+setTarget.value||5.5;db.settings.icr=+setICR.value||'';db.settings.isf=+setISF.value||'';db.settings.carb=+setCarb.value||0;save();alert('Настройки сохранены')}function saveLocaleSettings(){db.preferences=db.preferences||{};db.preferences.language=setLanguage.value||'ru';db.preferences.region=setRegion.value||'KG';db.preferences.units=db.preferences.units||{};db.preferences.units.glucose=setGlucoseUnit.value||'mmol/L';db.preferences.languageSync=db.preferences.languageSync||{};db.preferences.languageSync.mode=setLanguageSync.value||'device';if(db.preferences.languageSync.mode==='shared')db.preferences.languageSync.sharedLanguage=db.preferences.language;save();window.DMI18N.apply();renderSettings();}function renderSettings(){setTarget.value=db.profile.target||db.settings.target||'';setICR.innerHTML=icrOptions(db.profile.icr||db.settings.icr||'');setISF.innerHTML=isfOptions(db.profile.isf||db.settings.isf||'');setCarb.value=db.settings.carb||'';setLanguage.value=db.preferences?.language||'ru';setRegion.value=db.preferences?.region||'KG';setGlucoseUnit.value=db.preferences?.units?.glucose||'mmol/L';setLanguageSync.value=db.preferences?.languageSync?.mode||'device';window.DMI18N.apply()}
function setTransferStatus(msg,ok=false){let el=document.getElementById('transferStatus');if(el){el.textContent=msg;el.className=ok?'ok':'muted'}}
function exportData(){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(db,null,2)],{type:'application/json'}));a.download='my-diabetes-legacy-backup-'+today()+'.json';a.click()}
function exportPortableJson(){let env=core.transfer.createEnvelope(db,{sourceInstallationId:db.commercial?.installation?.id||db.device?.id||null,sourcePlatform:db.device?.platform||'web-desktop',encryption:'none'});DMBackup.download(JSON.stringify(env,null,2),'my-diabetes-portable-backup-'+today()+'.json');setTransferStatus('Переносимая копия создана. Храните её в защищённом месте.',true)}
async function createEncryptedBackup(){try{if(!DMBackup.hasCrypto())throw new Error('На этом устройстве недоступно шифрование Web Crypto.');let p1=prompt('Придумайте пароль для резервной копии. Пароль не сохраняется в приложении.');if(!p1)return;let p2=prompt('Повторите пароль.');if(p1!==p2)throw new Error('Пароли не совпадают.');let env=core.transfer.createEnvelope(db,{sourceInstallationId:db.commercial?.installation?.id||db.device?.id||null,sourcePlatform:db.device?.platform||'web-desktop',encryption:'AES-256-GCM'});let file=await DMBackup.encryptEnvelope(env,p1);DMBackup.download(JSON.stringify(file,null,2),'my-diabetes-encrypted-backup-'+today()+'.json');setTransferStatus('Зашифрованная копия создана. Пароль известен только вам.',true)}catch(e){setTransferStatus(e.message||'Не удалось создать копию.')}}
function importData(e){let f=e.target.files[0];if(!f)return;let r=new FileReader();r.onload=()=>{try{let raw=JSON.parse(r.result);let env=raw.manifest?raw:raw.data?.manifest?raw.data:null;if(env&&env.manifest){db=core.transfer.restore(db,env)}else{db=core.migrate(raw)}save();location.reload()}catch(err){alert('Ошибка импорта: '+(err.message||'проверьте файл'))}};r.readAsText(f)}
async function importEncryptedBackup(e){let f=e.target.files[0];if(!f)return;try{let raw=JSON.parse(await f.text());if(raw.format!=='my-diabetes-encrypted-backup')throw new Error('Это не зашифрованная копия приложения.');let p=prompt('Введите пароль резервной копии.');if(!p)return;let env=await DMBackup.decryptEnvelope(raw,p);let check=core.transfer.validateEnvelope(env);if(!check.valid)throw new Error('Проверка целостности не пройдена: '+check.errors.join(', '));db=core.transfer.restore(db,env);save();setTransferStatus('Данные восстановлены. Проверьте медицинские параметры перед использованием калькулятора.',true);setTimeout(()=>location.reload(),900)}catch(err){setTransferStatus(err.message||'Не удалось восстановить копию.')}}


